-- Function source: create_conversations_table
create or replace function update_conversations_updated_at()
returns trigger as $$
begin
    new.updated_at = now();
    return new;
end;
$$ language plpgsql SET search_path = public;

-- Function source: 20260318_unify_ai_gateway_sources
CREATE OR REPLACE FUNCTION public.update_ai_model_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql
SET search_path = public;

CREATE TRIGGER conversations_updated_at BEFORE UPDATE ON public.conversations FOR EACH ROW EXECUTE FUNCTION public.update_conversations_updated_at();
CREATE TRIGGER ai_models_updated_at BEFORE UPDATE ON public.ai_models FOR EACH ROW EXECUTE FUNCTION public.update_ai_model_updated_at();
CREATE TRIGGER ai_gateways_updated_at BEFORE UPDATE ON public.ai_gateways FOR EACH ROW EXECUTE FUNCTION public.update_ai_model_updated_at();
CREATE TRIGGER ai_model_gateway_bindings_updated_at BEFORE UPDATE ON public.ai_model_gateway_bindings FOR EACH ROW EXECUTE FUNCTION public.update_ai_model_updated_at();

-- Function source: 20260211_remove_service_role_key_phase2
CREATE OR REPLACE FUNCTION public.is_admin_user()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.users u
    WHERE u.id = auth.uid() AND u.is_admin = true
  );
$$;

-- Function source: 20260211_remove_service_role_key_phase2
CREATE OR REPLACE FUNCTION public.admin_get_auth_user_emails(p_user_ids uuid[])
RETURNS TABLE(user_id uuid, email text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'Only admin can read auth user emails' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT au.id, au.email::text
  FROM auth.users au
  WHERE au.id = ANY (p_user_ids);
END;
$$;

REVOKE ALL ON FUNCTION public.is_admin_user() FROM public;

GRANT EXECUTE ON FUNCTION public.is_admin_user() TO authenticated;

REVOKE ALL ON FUNCTION public.admin_get_auth_user_emails(uuid[]) FROM public;

GRANT EXECUTE ON FUNCTION public.admin_get_auth_user_emails(uuid[]) TO authenticated;

-- Function source: fix_login_attempts_rls
CREATE OR REPLACE FUNCTION record_login_attempt(
    p_email TEXT,
    p_success BOOLEAN
)
RETURNS void AS $$
BEGIN
    INSERT INTO login_attempts (email, success, attempt_at)
    VALUES (p_email, p_success, NOW());
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Failed to record login attempt: %', SQLERRM;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Function source: fix_login_attempts_rls
CREATE OR REPLACE FUNCTION check_login_attempts(p_email TEXT)
RETURNS TABLE(failed_count BIGINT) AS $$
BEGIN
    RETURN QUERY
    SELECT COUNT(*)::BIGINT
    FROM login_attempts
    WHERE email = p_email
    AND success = false
    AND attempt_at > NOW() - INTERVAL '15 minutes';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

