-- Only migration owners can invoke the shared Storage setup. A fresh local stack
-- runs it after Storage creates its real tables; an existing stack runs it here.
CREATE FUNCTION public.configure_agent_attachment_storage() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF to_regclass('storage.buckets') IS NULL OR to_regclass('storage.objects') IS NULL THEN RETURN; END IF;
  INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
  VALUES('agent-attachments','agent-attachments',false,10485760,ARRAY['image/jpeg','image/png','image/webp','text/plain'])
  ON CONFLICT(id) DO NOTHING;
  IF EXISTS(SELECT 1 FROM storage.buckets WHERE id='agent-attachments' AND public) THEN
    RAISE EXCEPTION 'Agent attachment bucket must be private';
  END IF;
  GRANT SELECT, INSERT, UPDATE, DELETE ON storage.objects TO authenticated;
  IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='agent_attachment_backend') THEN
    CREATE POLICY agent_attachment_backend ON storage.objects FOR ALL TO authenticated
      USING (bucket_id='agent-attachments' AND public.is_admin_user())
      WITH CHECK (bucket_id='agent-attachments' AND public.is_admin_user());
  END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.configure_agent_attachment_storage() FROM public,anon,authenticated,service_role;
SELECT public.configure_agent_attachment_storage();
NOTIFY pgrst, 'reload schema';


-- A question answer is a durable business command.  A second tab may lose the
-- first tab's clientRequestId, so the run lock must also deduplicate by the
-- stable question id and the complete answer payload.
CREATE OR REPLACE FUNCTION public.agent_submit_command(p_run_id uuid,p_request_id text,p_mode text,p_message jsonb)
RETURNS public.agent_run_commands LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.agent_runs; cmd public.agent_run_commands; messages jsonb; previous_write text; question_id text;
BEGIN
  SELECT * INTO r FROM public.agent_runs WHERE id=p_run_id FOR UPDATE;
  IF NOT FOUND OR (r.user_id IS DISTINCT FROM auth.uid() AND NOT coalesce(public.is_admin_user(),false) AND coalesce(auth.role(),'')<>'service_role') THEN
    RAISE EXCEPTION 'AGENT_RUN_NOT_FOUND' USING ERRCODE='42501';
  END IF;
  SELECT * INTO cmd FROM public.agent_run_commands WHERE run_id=p_run_id AND request_id=p_request_id;
  IF FOUND THEN
    IF cmd.original_message->>'content' IS DISTINCT FROM p_message->>'content' OR cmd.original_mode<>p_mode
      OR cmd.original_message#>'{metadata,agentAnswers}' IS DISTINCT FROM p_message#>'{metadata,agentAnswers}'
      OR cmd.original_message->'attachments' IS DISTINCT FROM p_message->'attachments' THEN
      RAISE EXCEPTION 'AGENT_REQUEST_MISMATCH' USING ERRCODE='22023';
    END IF;
    RETURN cmd;
  END IF;
  question_id:=NULLIF(p_message#>>'{metadata,agentQuestionId}','');
  IF p_mode='reply' AND question_id IS NOT NULL THEN
    SELECT * INTO cmd
      FROM public.agent_run_commands c
     WHERE c.run_id=p_run_id
       AND c.mode='reply'
       AND c.delivery_state<>'cancelled'
       AND coalesce(c.original_message,c.message)#>>'{metadata,agentQuestionId}'=question_id
       AND coalesce(c.original_message,c.message)->>'content' IS NOT DISTINCT FROM p_message->>'content'
       AND coalesce(c.original_message,c.message)->'metadata'->'agentAnswers' IS NOT DISTINCT FROM p_message->'metadata'->'agentAnswers'
       AND coalesce(c.original_message,c.message)->'attachments' IS NOT DISTINCT FROM p_message->'attachments'
     ORDER BY c.sequence
     LIMIT 1;
    IF FOUND THEN RETURN cmd; END IF;
    IF EXISTS (
      SELECT 1 FROM public.agent_run_commands c
       WHERE c.run_id=p_run_id AND c.mode='reply' AND c.delivery_state<>'cancelled'
         AND coalesce(c.original_message,c.message)#>>'{metadata,agentQuestionId}'=question_id
    ) THEN
      RAISE EXCEPTION 'AGENT_QUESTION_ALREADY_ANSWERED' USING ERRCODE='40001';
    END IF;
  END IF;
  IF r.status NOT IN ('queued','running','awaiting_input') OR r.cancel_requested THEN RAISE EXCEPTION 'AGENT_RUN_CLOSED' USING ERRCODE='22023'; END IF;
  IF p_mode NOT IN ('steer','follow_up','reply') OR p_message->>'role'<>'user' OR coalesce(btrim(p_message->>'content'),'')='' OR length(p_message->>'content')>32000 THEN RAISE EXCEPTION 'AGENT_INVALID_MESSAGE' USING ERRCODE='22023'; END IF;
  IF (SELECT count(*) FROM public.agent_run_commands WHERE run_id=p_run_id AND NOT consumed)>=50 THEN RAISE EXCEPTION 'AGENT_QUEUE_FULL' USING ERRCODE='22023'; END IF;
  IF p_mode='reply' AND r.checkpoint->>'questionId' IS NOT NULL AND r.checkpoint->>'questionId' IS DISTINCT FROM p_message#>>'{metadata,agentQuestionId}' THEN RAISE EXCEPTION 'AGENT_QUESTION_CHANGED' USING ERRCODE='40001'; END IF;
  INSERT INTO public.agent_run_commands(run_id,request_id,mode,message,original_message,original_mode,sort_order)
    VALUES(p_run_id,p_request_id,p_mode,p_message,p_message,p_mode,(SELECT coalesce(max(sort_order),0)+1024 FROM public.agent_run_commands WHERE run_id=p_run_id)) RETURNING * INTO cmd;
  -- Pending inputs stay in the business queue until the worker freezes them.
  UPDATE public.agent_runs SET status=CASE WHEN status='awaiting_input' AND p_mode='reply' THEN 'queued' ELSE status END,updated_at=now() WHERE id=p_run_id;
  PERFORM public.agent_emit(p_run_id,'command');
  RETURN cmd;
END;
$$;



CREATE TABLE public.user_agent_memory (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 80),
  content text NOT NULL CHECK (length(btrim(content)) BETWEEN 1 AND 2000),
  kind text NOT NULL DEFAULT 'preference' CHECK (kind IN ('preference','context')),
  fingerprint text GENERATED ALWAYS AS (md5(content)) STORED,
  source_run_id uuid REFERENCES public.agent_runs(id) ON DELETE SET NULL,
  source_text text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id,fingerprint)
);
ALTER TABLE public.user_agent_memory ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_agent_memory_owner ON public.user_agent_memory FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY user_agent_memory_worker_read ON public.user_agent_memory FOR SELECT TO authenticated USING (public.is_admin_user());
REVOKE ALL ON TABLE public.user_agent_memory FROM PUBLIC, anon, authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_agent_memory TO authenticated;

CREATE FUNCTION public.agent_memory_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM auth.uid() THEN PERFORM public.agent_require_admin(); END IF;
  IF NEW.source_run_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.agent_runs WHERE id=NEW.source_run_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'AGENT_MEMORY_SOURCE_OWNER'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,910));
  IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.user_agent_memory WHERE user_id=NEW.user_id AND fingerprint=md5(NEW.content)) AND (SELECT count(*) FROM public.user_agent_memory WHERE user_id=NEW.user_id)>=128 THEN RAISE EXCEPTION 'AGENT_MEMORY_LIMIT'; END IF;
  NEW.updated_at:=now(); RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_memory_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER agent_memory_guard BEFORE INSERT OR UPDATE ON public.user_agent_memory FOR EACH ROW EXECUTE FUNCTION public.agent_memory_guard();

CREATE FUNCTION public.agent_write_memory(p_run_id uuid,p_worker_id text,p_fence bigint,p_title text,p_content text,p_kind text,p_evidence text)
RETURNS public.user_agent_memory LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.agent_runs; m public.user_agent_memory;
BEGIN
  r:=public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  IF r.cancel_requested THEN RAISE EXCEPTION 'AGENT_CANCELLED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=r.user_id AND chat_preferences->>'memoryEnabled'='true') THEN RAISE EXCEPTION 'AGENT_MEMORY_DISABLED'; END IF;
  IF p_evidence IS NULL OR p_content IS NULL OR p_title IS NULL OR length(btrim(p_evidence))<8 OR length(p_evidence)>500 OR btrim(p_content)<>btrim(p_evidence) OR ((r.input->'userMessage'->>'role' IS DISTINCT FROM 'user' OR strpos(coalesce(r.input->'userMessage'->>'content',''),p_evidence)=0) AND NOT EXISTS(SELECT 1 FROM public.agent_run_commands WHERE run_id=r.id AND message->>'role'='user' AND delivery_state IN ('admitted','consumed') AND strpos(message->>'content',p_evidence)>0)) THEN RAISE EXCEPTION 'AGENT_MEMORY_EVIDENCE_REQUIRED'; END IF;
  INSERT INTO public.user_agent_memory(user_id,title,content,kind,source_run_id,source_text)
  VALUES(r.user_id,btrim(p_title),btrim(p_content),p_kind,r.id,p_evidence)
  ON CONFLICT(user_id,fingerprint) DO UPDATE SET title=excluded.title,kind=excluded.kind,source_run_id=excluded.source_run_id,source_text=excluded.source_text,updated_at=now()
  RETURNING * INTO m;
  RETURN m;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_write_memory(uuid,text,bigint,text,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agent_write_memory(uuid,text,bigint,text,text,text,text) TO authenticated;



-- Pi Durable 1.1.0 engine generation. New workers and new runs record
-- pi-durable/1.1.0; checkpoints written before the upgrade keep their recorded
-- pi-durable/1.0.4 marker. A worker may claim native (V2) runs of its own
-- generation or older, never a newer one: the upgraded worker resumes
-- in-flight runs, while a stale binary cannot adopt a run it does not
-- understand.
CREATE OR REPLACE FUNCTION public.agent_worker_heartbeat(p_worker_id text,p_engine text DEFAULT 'pi-agent-core/1.0.2')
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
  PERFORM public.agent_require_admin();
  IF p_engine NOT IN ('pi-agent-core/1.0.2','pi-durable/1.0.4','pi-durable/1.1.0') THEN
    RAISE EXCEPTION 'AGENT_ENGINE_UNSUPPORTED' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.agent_workers(id,heartbeat_at,engine) VALUES(p_worker_id,now(),p_engine)
    ON CONFLICT(id) DO UPDATE SET heartbeat_at=excluded.heartbeat_at,engine=excluded.engine;
END;
$$;

CREATE OR REPLACE FUNCTION public.agent_claim_run(p_worker_id text) RETURNS public.agent_runs
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.agent_runs; worker_engine text;
BEGIN
  PERFORM public.agent_require_admin();
  SELECT engine INTO worker_engine FROM public.agent_workers WHERE id=p_worker_id;
  SELECT * INTO r FROM public.agent_runs
    WHERE (status='queued' OR (status IN ('running','cancelling') AND lease_until<now()))
      AND (coalesce(checkpoint->>'version','1')='1' OR (
        checkpoint->>'version'='2' AND (
          (worker_engine='pi-durable/1.1.0' AND checkpoint#>>'{durable,engine}' IN ('pi-durable/1.0.4','pi-durable/1.1.0')) OR
          (worker_engine='pi-durable/1.0.4' AND checkpoint#>>'{durable,engine}'='pi-durable/1.0.4'))))
    ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.agent_runs SET status=CASE WHEN cancel_requested THEN 'cancelling' ELSE 'running' END,
    worker_id=p_worker_id,fence=fence+1,lease_until=now()+interval '60 seconds',updated_at=now()
    WHERE id=r.id RETURNING * INTO r;
  PERFORM public.agent_emit(r.id,'claimed');
  SELECT * INTO r FROM public.agent_runs WHERE id=r.id;
  RETURN r;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_worker_heartbeat(text,text),public.agent_claim_run(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agent_worker_heartbeat(text,text),public.agent_claim_run(text) TO authenticated,service_role;


-- Keep existing model settings valid while supporting Pi's xhigh/max levels.
ALTER TABLE public.ai_models
  DROP CONSTRAINT IF EXISTS ai_models_default_reasoning_effort_check;
ALTER TABLE public.ai_models
  ADD CONSTRAINT ai_models_default_reasoning_effort_check
  CHECK (default_reasoning_effort IS NULL OR default_reasoning_effort IN ('minimal', 'low', 'medium', 'high', 'xhigh', 'max'));



-- Runtime upgrades replace the supported engine instead of continuing old logs.
CREATE OR REPLACE FUNCTION public.agent_worker_heartbeat(p_worker_id text,p_engine text DEFAULT 'pi-durable/1.1.0')
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
  PERFORM public.agent_require_admin();
  IF p_engine IS DISTINCT FROM 'pi-durable/1.1.0' THEN
    RAISE EXCEPTION 'AGENT_ENGINE_UNSUPPORTED' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.agent_workers(id,heartbeat_at,engine) VALUES(p_worker_id,now(),p_engine)
    ON CONFLICT(id) DO UPDATE SET heartbeat_at=excluded.heartbeat_at,engine=excluded.engine;
END;
$$;

CREATE OR REPLACE FUNCTION public.agent_claim_run(p_worker_id text) RETURNS public.agent_runs
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.agent_runs;
BEGIN
  PERFORM public.agent_require_admin();
  IF NOT EXISTS(SELECT 1 FROM public.agent_workers WHERE id=p_worker_id AND engine='pi-durable/1.1.0') THEN RETURN NULL; END IF;
  SELECT * INTO r FROM public.agent_runs
    WHERE (status='queued' OR (status IN ('running','cancelling') AND lease_until<now()))
      AND checkpoint->>'version'='2' AND checkpoint#>>'{durable,engine}'='pi-durable/1.1.0'
    ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.agent_runs SET status=CASE WHEN cancel_requested THEN 'cancelling' ELSE 'running' END,
    worker_id=p_worker_id,fence=fence+1,lease_until=now()+interval '60 seconds',updated_at=now()
    WHERE id=r.id RETURNING * INTO r;
  PERFORM public.agent_emit(r.id,'claimed');
  SELECT * INTO r FROM public.agent_runs WHERE id=r.id;
  RETURN r;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_worker_heartbeat(text,text),public.agent_claim_run(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agent_worker_heartbeat(text,text),public.agent_claim_run(text) TO authenticated,service_role;

-- Reuse admission and settlement; never duplicate their credit or chart logic.
DO $migration$
DECLARE definition text; anchor text := 'PERFORM public.agent_require_admin();';
  guard text := 'IF coalesce(p_checkpoint->>''version'','''')<>''2'' OR coalesce(p_checkpoint#>>''{durable,engine}'','''')<>''pi-durable/1.1.0'' THEN RAISE EXCEPTION ''AGENT_ENGINE_UNSUPPORTED'' USING ERRCODE=''22023''; END IF;';
BEGIN
  SELECT pg_catalog.pg_get_functiondef('public.agent_create_run(uuid,uuid,uuid,text,text,jsonb,jsonb,jsonb,jsonb,boolean)'::regprocedure) INTO definition;
  IF position(guard IN definition)=0 THEN
    IF position(anchor IN definition)=0 THEN RAISE EXCEPTION 'Review agent_create_run before installing current engine guard'; END IF;
    EXECUTE replace(definition,anchor,anchor||E'\n  '||guard);
  END IF;
END; $migration$;

-- Fence old owners and settle all unfinished unsupported tasks once. Completed
-- history and artifacts remain readable. Empty failed work follows the normal
-- refund rule; partial replies retain the existing charging policy.
DO $retire$
DECLARE r public.agent_runs; message jsonb;
  old_claims text := current_setting('request.jwt.claims',true);
  old_role text := current_setting('request.jwt.claim.role',true);
BEGIN
  PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  FOR r IN SELECT * FROM public.agent_runs WHERE status IN ('queued','running','awaiting_input','cancelling')
    AND (coalesce(checkpoint->>'version','')<>'2' OR coalesce(checkpoint#>>'{durable,engine}','')<>'pi-durable/1.1.0') FOR UPDATE LOOP
    UPDATE public.agent_runs SET worker_id='engine-retirement',fence=fence+1,lease_until=now()+interval '60 seconds',status='running'
      WHERE id=r.id RETURNING * INTO r;
    message:=jsonb_set(r.public_message,'{agent}',coalesce(r.public_message->'agent','{}'::jsonb)||jsonb_build_object('error','运行版本已更新，请重新发起任务。'));
    PERFORM public.agent_finish_run(r.id,r.worker_id,r.fence,'failed',r.checkpoint,message,NULL);
    UPDATE public.agent_run_commands SET consumed=true,delivery_state='cancelled' WHERE run_id=r.id AND NOT consumed;
  END LOOP;
  PERFORM set_config('request.jwt.claims',coalesce(old_claims,''),true);
  PERFORM set_config('request.jwt.claim.role',coalesce(old_role,''),true);
END; $retire$;

NOTIFY pgrst, 'reload schema';


-- Public read-only conversation shares.
-- A share is an owner-created, sanitised snapshot of a conversation's visible branch.
-- Owners read their own rows through RLS; every write goes through the owner RPCs below,
-- and anonymous visitors can only resolve a single active snapshot by its unguessable token.
CREATE TABLE public.conversation_shares (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token text NOT NULL UNIQUE CHECK (token ~ '^[A-Za-z0-9_-]{43}$'),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,
  title text NOT NULL DEFAULT '' CHECK (char_length(title) <= 200),
  snapshot jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(snapshot) = 'array'),
  include_charts boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz
);
CREATE UNIQUE INDEX conversation_shares_active_conversation_idx ON public.conversation_shares (conversation_id) WHERE revoked_at IS NULL;
CREATE INDEX conversation_shares_user_created_idx ON public.conversation_shares (user_id, created_at DESC);

ALTER TABLE public.conversation_shares ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversation_shares_owner_select ON public.conversation_shares FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
REVOKE ALL ON TABLE public.conversation_shares FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.conversation_shares TO authenticated;

-- Create or refresh the conversation's single active share. Refreshing keeps the existing token,
-- so links already handed out stay valid. Rejects foreign conversations, running Agent tasks and
-- snapshots built from an outdated conversation state.
CREATE FUNCTION public.upsert_conversation_share(p_conversation uuid,p_token text,p_title text,p_snapshot jsonb,p_include_charts boolean,p_source_updated_at timestamptz) RETURNS public.conversation_shares
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE source public.conversations; share public.conversation_shares;
BEGIN
 SELECT * INTO source FROM public.conversations WHERE id=p_conversation AND user_id=auth.uid() FOR UPDATE;
 IF source.id IS NULL THEN RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE='42501'; END IF;
 IF EXISTS (SELECT 1 FROM public.agent_runs WHERE conversation_id=p_conversation AND status IN ('queued','running','awaiting_input','cancelling')) THEN
  RAISE EXCEPTION 'CONVERSATION_BUSY' USING ERRCODE='55006';
 END IF;
 IF source.updated_at IS DISTINCT FROM p_source_updated_at THEN RAISE EXCEPTION 'SHARE_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;
 IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot)<>'array' OR octet_length(p_snapshot::text)>1048576 THEN
  RAISE EXCEPTION 'SHARE_SNAPSHOT_INVALID' USING ERRCODE='22023';
 END IF;
 UPDATE public.conversation_shares
    SET title=left(coalesce(p_title,''),200), snapshot=p_snapshot, include_charts=coalesce(p_include_charts,false), updated_at=now()
  WHERE conversation_id=p_conversation AND revoked_at IS NULL
  RETURNING * INTO share;
 IF share.id IS NULL THEN
  INSERT INTO public.conversation_shares (token,user_id,conversation_id,title,snapshot,include_charts)
  VALUES (p_token,auth.uid(),p_conversation,left(coalesce(p_title,''),200),p_snapshot,coalesce(p_include_charts,false))
  RETURNING * INTO share;
 END IF;
 RETURN share;
END;
$$;
REVOKE ALL ON FUNCTION public.upsert_conversation_share(uuid,text,text,jsonb,boolean,timestamptz) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.upsert_conversation_share(uuid,text,text,jsonb,boolean,timestamptz) TO authenticated;

-- Revoke the active share and purge its content; the row only remains as an owner audit trail.
CREATE FUNCTION public.revoke_conversation_share(p_conversation uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.conversations WHERE id=p_conversation AND user_id=auth.uid()) THEN
  RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING ERRCODE='42501';
 END IF;
 UPDATE public.conversation_shares SET revoked_at=now(), updated_at=now(), snapshot='[]'::jsonb, title=''
  WHERE conversation_id=p_conversation AND user_id=auth.uid() AND revoked_at IS NULL;
 RETURN FOUND;
END;
$$;
REVOKE ALL ON FUNCTION public.revoke_conversation_share(uuid) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.revoke_conversation_share(uuid) TO authenticated;

-- Anonymous lookup of one active share. Exposes only presentation fields, never owner or conversation ids.
CREATE FUNCTION public.get_conversation_share(p_token text) RETURNS TABLE (title text, snapshot jsonb, include_charts boolean, created_at timestamptz, updated_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT s.title, s.snapshot, s.include_charts, s.created_at, s.updated_at
   FROM public.conversation_shares s
  WHERE p_token ~ '^[A-Za-z0-9_-]{43}$' AND s.token=p_token AND s.revoked_at IS NULL
  LIMIT 1
$$;
REVOKE ALL ON FUNCTION public.get_conversation_share(text) FROM public;
GRANT EXECUTE ON FUNCTION public.get_conversation_share(text) TO anon, authenticated;



-- Pi Durable 1.3.0 replaces 1.1.0. Its tool tasks are version 2 (model-issued or
-- nested), and code mode, nested calls and deferred tools add task and agent
-- documents a 1.1.0 worker cannot read. Only the current engine executes.
CREATE OR REPLACE FUNCTION public.agent_worker_heartbeat(p_worker_id text,p_engine text DEFAULT 'pi-durable/1.3.0')
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
  PERFORM public.agent_require_admin();
  IF p_engine IS DISTINCT FROM 'pi-durable/1.3.0' THEN
    RAISE EXCEPTION 'AGENT_ENGINE_UNSUPPORTED' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.agent_workers(id,heartbeat_at,engine) VALUES(p_worker_id,now(),p_engine)
    ON CONFLICT(id) DO UPDATE SET heartbeat_at=excluded.heartbeat_at,engine=excluded.engine;
END;
$$;

CREATE OR REPLACE FUNCTION public.agent_claim_run(p_worker_id text) RETURNS public.agent_runs
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.agent_runs;
BEGIN
  PERFORM public.agent_require_admin();
  IF NOT EXISTS(SELECT 1 FROM public.agent_workers WHERE id=p_worker_id AND engine='pi-durable/1.3.0') THEN RETURN NULL; END IF;
  SELECT * INTO r FROM public.agent_runs
    WHERE (status='queued' OR (status IN ('running','cancelling') AND lease_until<now()))
      AND checkpoint->>'version'='2' AND checkpoint#>>'{durable,engine}'='pi-durable/1.3.0'
    ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.agent_runs SET status=CASE WHEN cancel_requested THEN 'cancelling' ELSE 'running' END,
    worker_id=p_worker_id,fence=fence+1,lease_until=now()+interval '60 seconds',updated_at=now()
    WHERE id=r.id RETURNING * INTO r;
  PERFORM public.agent_emit(r.id,'claimed');
  SELECT * INTO r FROM public.agent_runs WHERE id=r.id;
  RETURN r;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_worker_heartbeat(text,text),public.agent_claim_run(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agent_worker_heartbeat(text,text),public.agent_claim_run(text) TO authenticated,service_role;

-- Swap the admission guard the current-engine migration installed; any other
-- definition is unreviewed and stops the migration.
DO $migration$
DECLARE definition text;
  old_guard text := 'IF coalesce(p_checkpoint->>''version'','''')<>''2'' OR coalesce(p_checkpoint#>>''{durable,engine}'','''')<>''pi-durable/1.1.0'' THEN RAISE EXCEPTION ''AGENT_ENGINE_UNSUPPORTED'' USING ERRCODE=''22023''; END IF;';
  new_guard text := 'IF coalesce(p_checkpoint->>''version'','''')<>''2'' OR coalesce(p_checkpoint#>>''{durable,engine}'','''')<>''pi-durable/1.3.0'' THEN RAISE EXCEPTION ''AGENT_ENGINE_UNSUPPORTED'' USING ERRCODE=''22023''; END IF;';
BEGIN
  SELECT pg_catalog.pg_get_functiondef('public.agent_create_run(uuid,uuid,uuid,text,text,jsonb,jsonb,jsonb,jsonb,boolean)'::regprocedure) INTO definition;
  IF position(new_guard IN definition)=0 THEN
    IF position(old_guard IN definition)=0 THEN RAISE EXCEPTION 'Review agent_create_run before installing the pi-durable/1.3.0 guard'; END IF;
    EXECUTE replace(definition,old_guard,new_guard);
  END IF;
END; $migration$;

-- Fence old owners and settle all unfinished 1.1.0 tasks once, through the
-- existing settlement: empty failed work is refunded, partial replies keep the
-- charge. Completed history and artifacts stay readable.
DO $retire$
DECLARE r public.agent_runs; message jsonb;
  old_claims text := current_setting('request.jwt.claims',true);
  old_role text := current_setting('request.jwt.claim.role',true);
BEGIN
  PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  FOR r IN SELECT * FROM public.agent_runs WHERE status IN ('queued','running','awaiting_input','cancelling')
    AND (coalesce(checkpoint->>'version','')<>'2' OR coalesce(checkpoint#>>'{durable,engine}','')<>'pi-durable/1.3.0') FOR UPDATE LOOP
    UPDATE public.agent_runs SET worker_id='engine-retirement',fence=fence+1,lease_until=now()+interval '60 seconds',status='running'
      WHERE id=r.id RETURNING * INTO r;
    message:=jsonb_set(r.public_message,'{agent}',coalesce(r.public_message->'agent','{}'::jsonb)||jsonb_build_object('error','运行版本已更新，请重新发起任务。'));
    PERFORM public.agent_finish_run(r.id,r.worker_id,r.fence,'failed',r.checkpoint,message,NULL);
    UPDATE public.agent_run_commands SET consumed=true,delivery_state='cancelled' WHERE run_id=r.id AND NOT consumed;
  END LOOP;
  PERFORM set_config('request.jwt.claims',coalesce(old_claims,''),true);
  PERFORM set_config('request.jwt.claim.role',coalesce(old_role,''),true);
END; $retire$;

NOTIFY pgrst, 'reload schema';


-- Saving an Agent chart to the chart library is the user's choice on the board,
-- through the result pages' own save endpoint; the model no longer selects
-- results for the task's settlement to save. agent_finish_run stops saving
-- charts and drops p_record (unused since 20261007_100000); agent_cache_tool
-- stops storing a chart payload; the artifact columns that only these two
-- functions wrote are dropped. Settlement, command, refund and message rules
-- are unchanged. Earlier answers keep their artifact parts and chart links in
-- their messages; the saved charts themselves are untouched.

DROP FUNCTION public.agent_finish_run(uuid,text,bigint,text,jsonb,jsonb,jsonb);
CREATE FUNCTION public.agent_finish_run(p_run_id uuid,p_worker_id text,p_fence bigint,p_status text,p_checkpoint jsonb,p_message jsonb)
RETURNS public.agent_runs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.agent_runs; final_status text;
BEGIN
  r:=public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  IF p_status NOT IN ('completed','awaiting_input','failed','cancelled') THEN RAISE EXCEPTION 'AGENT_INVALID_STATUS'; END IF;
  final_status:=CASE WHEN r.cancel_requested THEN 'cancelled' ELSE p_status END;
  IF final_status IN ('completed','awaiting_input') AND EXISTS(SELECT 1 FROM public.agent_run_commands WHERE run_id=p_run_id AND NOT consumed AND (final_status<>'awaiting_input' OR (mode='reply' AND NOT durable_admitted))) THEN
    final_status:='queued';
  END IF;
  IF final_status IN ('failed','cancelled') AND r.billing='charged' AND coalesce(btrim(p_message->>'content'),'')='' AND r.record_id IS NULL THEN
    IF public.increment_ai_chat_count(r.user_id,1) IS NULL THEN RAISE EXCEPTION 'AGENT_REFUND_FAILED'; END IF;
    r.billing:='refunded';
  END IF;
  p_message:=jsonb_set(p_message,'{agent,status}',to_jsonb(final_status));
  UPDATE public.agent_runs SET status=final_status,checkpoint=p_checkpoint,public_message=p_message,billing=r.billing,
    lease_until=NULL,worker_id=NULL,updated_at=now() WHERE id=p_run_id RETURNING * INTO r;
  IF final_status IN ('completed','failed','cancelled') THEN DELETE FROM public.agent_run_credentials WHERE run_id=p_run_id; END IF;
  PERFORM public.agent_emit(p_run_id,final_status);
  PERFORM public.agent_sync_message(p_run_id);
  SELECT * INTO r FROM public.agent_runs WHERE id=p_run_id;
  RETURN r;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_finish_run(uuid,text,bigint,text,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agent_finish_run(uuid,text,bigint,text,jsonb,jsonb) TO authenticated,service_role;

DROP FUNCTION public.agent_cache_tool(uuid,text,bigint,text,text,text,jsonb,jsonb,jsonb);
CREATE FUNCTION public.agent_cache_tool(p_run_id uuid,p_worker_id text,p_fence bigint,p_call_id text,p_tool_name text,p_kind text,p_args jsonb,p_result jsonb)
RETURNS public.agent_run_artifacts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a public.agent_run_artifacts;
BEGIN
  PERFORM public.agent_require_lease(p_run_id,p_worker_id,p_fence);
  INSERT INTO public.agent_run_artifacts(run_id,call_id,tool_name,kind,args,result)
    VALUES(p_run_id,p_call_id,p_tool_name,p_kind,p_args,p_result) ON CONFLICT(run_id,call_id) DO NOTHING;
  SELECT * INTO STRICT a FROM public.agent_run_artifacts WHERE run_id=p_run_id AND call_id=p_call_id;
  IF a.tool_name<>p_tool_name OR a.args IS DISTINCT FROM p_args OR a.kind<>p_kind THEN RAISE EXCEPTION 'AGENT_TOOL_CALL_MISMATCH'; END IF;
  RETURN a;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_cache_tool(uuid,text,bigint,text,text,text,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.agent_cache_tool(uuid,text,bigint,text,text,text,jsonb,jsonb) TO authenticated,service_role;

-- No index, constraint or policy uses these columns.
ALTER TABLE public.agent_run_artifacts DROP COLUMN chart_payload, DROP COLUMN chart_id, DROP COLUMN chart_type;

